set-variable.value:
@{
      var routes = JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("{{intake-backends}}")));
      var route = routes[context.Request.MatchedParameters["consumer"]];
      return route == null ? "" : route.ToString(Newtonsoft.Json.Formatting.None);
    }

return-response.set-body:
@{
            return new JObject(
              new JProperty("type", "https://github.com/azure-intelligence-domain/integration-platform/blob/main/docs/problems/unknown-consumer.md"),
              new JProperty("title", "Unknown Consumer"),
              new JProperty("status", 404),
              new JProperty("detail", "No consumer of this name is routed (routing/consumers.yaml)."),
              new JProperty("instance", context.Request.OriginalUrl.Path)
            ).ToString();
          }

@{
            return new JObject(
              new JProperty("type", "https://github.com/azure-intelligence-domain/integration-platform/blob/main/docs/problems/event-grid-token-required.md"),
              new JProperty("title", "Event Grid Token Required"),
              new JProperty("status", 401),
              new JProperty("detail", "Only Event Grid, with the managed identity of a platform topic, delivers events."),
              new JProperty("instance", context.Request.OriginalUrl.Path)
            ).ToString();
          }
